/* ===========================================================================
   Starfall Academy — character + compendium seed data
   ---------------------------------------------------------------------------
   Ported from public/character-sheet/data.js (window.SF_DATA) to a typed ES
   module. This is the offline/standalone seed + reference data; the live
   Compendium (src/sheet/data/compendium.ts) overlays the DB rows on top of the
   `compendium` / class arrays here, falling back to these when a tab is
   unreachable.
   =========================================================================== */
import type {
  Bonus,
  CharacterVitals,
  CompendiumCat,
  CompendiumEntry,
  Condition,
  MagicSchool,
  Move,
  Spell,
  Stat,
  Tone,
} from "../types";

/* ----------------------------------------------------------- seed-only -- */

export interface House {
  id: string;
  name: string;
  tone: Tone;
  color: string;
  animal: string;
  blurb: string;
}

export interface CreationYear {
  id: string;
  label: string;
  roman: string;
  quick: { stat: number; subject: number; skill: number };
  custom: number;
  limit: number;
  spells: { Basic: number; Standard: number; Advanced: number };
}

export interface StartingWand {
  id: string;
  name: string;
  kind: "stat" | "ability";
  value: number;
  count: number;
  grant: string;
  desc: string;
}

export interface CreationRules {
  years: CreationYear[];
  custom: {
    statCost: number;
    abilityCost: number;
    classRankCost: number;
    wandPer: number;
    artifactPer: number;
    itemPer: number;
  };
  classDefault: { single: number; double: number; maxClasses: number };
  startingMaterials: number;
  yields: {
    alchemyPotionMax: number;
    runologyGlyphsPerRank: number;
    wandcraftMatPerRank: number;
    herbalismPlantMat: number;
  };
  startingWands: StartingWand[];
}

export interface RosterSeedMember {
  id: string;
  name: string;
  house: string;
  tone: Tone;
  initials: string;
  active?: boolean;
}

/** A roll in the demo "conjure" pools / opening ledger. `hl` is a higher-level
 *  text function; the rest feed makeRoll(). */
export interface PoolRoll {
  whoId?: string;
  actor?: string;
  gm?: boolean;
  label: string;
  kind: string;
  stat: string;
  mod: number;
  dc?: number | null;
  meta?: string[];
  detail?: string | null;
  success?: string | null;
  fail?: string | null;
  hl?: (deg: number, s: boolean) => string;
  dice?: number[];
  sit?: number;
  sitReason?: string;
}

export interface SeedData {
  character: CharacterVitals;
  houses: House[];
  creation: CreationRules;
  roster: RosterSeedMember[];
  stats: Stat[];
  magicSchools: MagicSchool[];
  spells: Spell[];
  conditions: Condition[];
  moves: Move[];
  bonuses: Bonus[];
  compendiumCats: CompendiumCat[];
  compendium: CompendiumEntry[];
  partyPool: PoolRoll[];
  gmPool: PoolRoll[];
  gmInflection: PoolRoll;
  ledgerSeed: PoolRoll[];
}

